-- Real Solvex AC service catalog, transcribed and rebranded from a
-- reference AC service/price document. Idempotent: upserts by slug, so
-- re-running after a content edit updates existing rows rather than
-- duplicating them.

-- The old demo AC services are superseded by the real catalog below.
-- Deactivated, not deleted (orders/tickets may still reference them).
UPDATE services SET active = 0 WHERE slug = 'ac-cleaning';
UPDATE services SET active = 0 WHERE slug = 'ac-health-checkup';
UPDATE services SET active = 0 WHERE slug = 'ac-gas-refill';

-- AC Basic Service
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-basic-service', 'AC Basic Service', 'Filter cleaning, panel wipe-down, and a full diagnostic check.', 30, 1, 1, 'AC Basic Service is a fundamental maintenance offering that includes essential tasks such as inspecting filters, checking refrigerant levels, and inspecting the overall condition of your air conditioning unit. This service ensures optimal performance and longevity for your AC system.', '["Cleaning of Air Filters: Thorough cleaning of air filters to remove dust, dirt, and debris, ensuring optimal airflow.","AC Panel Cleaning: Wiping down the AC panel to remove dust and grime, enhancing overall cleanliness.","Checking and Testing of Electrical Parts: Inspection and testing of electrical components for proper functioning and safety.","Flushing the Drainage System: Clearing out the drainage system to prevent clogs and ensure proper water drainage.","Compressor Health Check: Assessment of the compressor''s condition to ensure it is operating efficiently.","Gas Level Check: Checking the refrigerant gas level to ensure optimal cooling performance.","Minor Problem-Fixing: Addressing minor issues without additional accessories or gas replenishment."]', '["The service does not cover the cost of gas refilling if needed.","The service does not include any repair work. If repairs are needed, our team will provide recommendations and a separate quotation.","Any required replacement parts are not included in the service cost and will be quoted separately.","Basic wash does not include any outdoor cleaning, for outdoor AC jet wash or AC master service needs to be taken.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How often should I schedule AC basic service?","a":"It''s recommended to schedule AC basic service at least 3-4 times a year to ensure efficient performance."},{"q":"Will the service improve cooling efficiency?","a":"Yes, regular maintenance can help improve cooling efficiency by ensuring all components are clean and functioning properly."},{"q":"Is gas refill included in the basic service?","a":"No, gas refill is not included in the basic service but can be provided as an additional service if needed."},{"q":"Can I request additional services during the basic service visit?","a":"Yes, you can request additional services, and our technicians will provide you with a quote for the extra work."},{"q":"What should I do if I notice any issues after the service?","a":"If you experience any issues after the service, please contact our customer support team, and we''ll address them promptly."},{"q":"Is the service warranty included?","a":"Yes, we provide a 7-day service warranty for the basic service, ensuring customer satisfaction and peace of mind."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-basic-service');
UPDATE services SET name = 'AC Basic Service', short_desc = 'Filter cleaning, panel wipe-down, and a full diagnostic check.', duration_min = 30, sort = 1, active = 1, about_md = 'AC Basic Service is a fundamental maintenance offering that includes essential tasks such as inspecting filters, checking refrigerant levels, and inspecting the overall condition of your air conditioning unit. This service ensures optimal performance and longevity for your AC system.', included_json = '["Cleaning of Air Filters: Thorough cleaning of air filters to remove dust, dirt, and debris, ensuring optimal airflow.","AC Panel Cleaning: Wiping down the AC panel to remove dust and grime, enhancing overall cleanliness.","Checking and Testing of Electrical Parts: Inspection and testing of electrical components for proper functioning and safety.","Flushing the Drainage System: Clearing out the drainage system to prevent clogs and ensure proper water drainage.","Compressor Health Check: Assessment of the compressor''s condition to ensure it is operating efficiently.","Gas Level Check: Checking the refrigerant gas level to ensure optimal cooling performance.","Minor Problem-Fixing: Addressing minor issues without additional accessories or gas replenishment."]', not_included_json = '["The service does not cover the cost of gas refilling if needed.","The service does not include any repair work. If repairs are needed, our team will provide recommendations and a separate quotation.","Any required replacement parts are not included in the service cost and will be quoted separately.","Basic wash does not include any outdoor cleaning, for outdoor AC jet wash or AC master service needs to be taken.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', faqs_json = '[{"q":"How often should I schedule AC basic service?","a":"It''s recommended to schedule AC basic service at least 3-4 times a year to ensure efficient performance."},{"q":"Will the service improve cooling efficiency?","a":"Yes, regular maintenance can help improve cooling efficiency by ensuring all components are clean and functioning properly."},{"q":"Is gas refill included in the basic service?","a":"No, gas refill is not included in the basic service but can be provided as an additional service if needed."},{"q":"Can I request additional services during the basic service visit?","a":"Yes, you can request additional services, and our technicians will provide you with a quote for the extra work."},{"q":"What should I do if I notice any issues after the service?","a":"If you experience any issues after the service, please contact our customer support team, and we''ll address them promptly."},{"q":"Is the service warranty included?","a":"Yes, we provide a 7-day service warranty for the basic service, ensuring customer satisfaction and peace of mind."}]' WHERE slug = 'ac-basic-service';
INSERT INTO service_prices (service_id, combo_key, price) SELECT id, '', 599 FROM services WHERE slug = 'ac-basic-service' AND NOT EXISTS (SELECT 1 FROM service_prices WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-basic-service') AND combo_key = '');
UPDATE service_prices SET price = 599 WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-basic-service') AND combo_key = '';
INSERT INTO service_costing (service_id, material, tools, resource_count, resource_cost, service_time_label, travel_cost, internal_cost, sop_md) SELECT id, 'No', 'Regular Tools', '2', 300, '30 min', 250, 550, NULL FROM services WHERE slug = 'ac-basic-service' AND NOT EXISTS (SELECT 1 FROM service_costing WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-basic-service'));
