-- Power Consumption Check-up
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-power-consumption-checkup', 'Power Consumption Check-up', 'Full evaluation of your AC''s energy usage, with cost-reduction advice.', 30, 2, 1, 'AC Power Consumption Check-Up involves evaluating the energy usage of your air conditioning system to identify any inefficiencies and recommend measures to improve energy efficiency. This service helps optimize your AC''s performance while reducing energy costs.

Important note: We provide a power consumption checkup report based on the present scenario. However, in the event of circumstances such as natural disasters or power grid failure, or low voltage supply, this report may not be applicable and may require another checkup. We are not responsible for such situations.', '["AC Circuit Checkup: Thorough examination of the AC circuit to ensure proper functioning and safety.","Electricity Checkup: Assessment of electricity supply to the AC unit to identify any irregularities or issues.","Wiring Checkup: Inspection of the wiring system associated with the AC unit to detect any faults or deficiencies.","Filter Cleaning: Cleaning of the AC filters to improve airflow and efficiency.","Cooling Measurement: Measurement of cooling performance to assess efficiency and identify potential improvements.","Estimate of Electricity Consumption: Calculation of estimated electricity consumption in units or kilowatts based on usage patterns and AC efficiency.","Advice on AC Cost Control: Providing recommendations and advice on optimizing AC usage to control electricity costs."]', '["Hanging Charge: Additional charges may apply if hanging is required for outdoor units.","Electric Equipment Charge: Charges for any electric equipment or components needed for repairs or replacements.","Additional Service Charges: Charges for any additional parts or services required to address electricity consumption issues.","Other Work Scope: Any work beyond the specified scope of the AC power consumption checkup service is excluded.","Gas Refilling: The service does not cover the cost of gas refilling if needed."]', '[{"q":"How often should I schedule an AC power consumption checkup?","a":"It''s recommended to schedule the checkup annually to ensure optimal performance and efficiency."},{"q":"Will the service help reduce my electricity bills?","a":"The service aims to identify areas for optimization to potentially reduce electricity bills, but actual savings may vary."},{"q":"Can the service detect electrical faults in my AC unit?","a":"Yes, the checkup includes a comprehensive inspection of the AC circuit and wiring to detect any faults."},{"q":"How long does the checkup take?","a":"The duration depends on the complexity of the assessment but typically takes around 1-2 hours."},{"q":"What should I do if I notice unusual electricity consumption after the checkup?","a":"If you notice any abnormalities, contact our service team immediately for further assistance and evaluation."},{"q":"Are there any preventive measures to control AC costs?","a":"Yes, our experts will provide valuable advice and recommendations on optimizing AC usage to control electricity costs."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-power-consumption-checkup');
UPDATE services SET name = 'Power Consumption Check-up', short_desc = 'Full evaluation of your AC''s energy usage, with cost-reduction advice.', duration_min = 30, sort = 2, active = 1, about_md = 'AC Power Consumption Check-Up involves evaluating the energy usage of your air conditioning system to identify any inefficiencies and recommend measures to improve energy efficiency. This service helps optimize your AC''s performance while reducing energy costs.

Important note: We provide a power consumption checkup report based on the present scenario. However, in the event of circumstances such as natural disasters or power grid failure, or low voltage supply, this report may not be applicable and may require another checkup. We are not responsible for such situations.', included_json = '["AC Circuit Checkup: Thorough examination of the AC circuit to ensure proper functioning and safety.","Electricity Checkup: Assessment of electricity supply to the AC unit to identify any irregularities or issues.","Wiring Checkup: Inspection of the wiring system associated with the AC unit to detect any faults or deficiencies.","Filter Cleaning: Cleaning of the AC filters to improve airflow and efficiency.","Cooling Measurement: Measurement of cooling performance to assess efficiency and identify potential improvements.","Estimate of Electricity Consumption: Calculation of estimated electricity consumption in units or kilowatts based on usage patterns and AC efficiency.","Advice on AC Cost Control: Providing recommendations and advice on optimizing AC usage to control electricity costs."]', not_included_json = '["Hanging Charge: Additional charges may apply if hanging is required for outdoor units.","Electric Equipment Charge: Charges for any electric equipment or components needed for repairs or replacements.","Additional Service Charges: Charges for any additional parts or services required to address electricity consumption issues.","Other Work Scope: Any work beyond the specified scope of the AC power consumption checkup service is excluded.","Gas Refilling: The service does not cover the cost of gas refilling if needed."]', faqs_json = '[{"q":"How often should I schedule an AC power consumption checkup?","a":"It''s recommended to schedule the checkup annually to ensure optimal performance and efficiency."},{"q":"Will the service help reduce my electricity bills?","a":"The service aims to identify areas for optimization to potentially reduce electricity bills, but actual savings may vary."},{"q":"Can the service detect electrical faults in my AC unit?","a":"Yes, the checkup includes a comprehensive inspection of the AC circuit and wiring to detect any faults."},{"q":"How long does the checkup take?","a":"The duration depends on the complexity of the assessment but typically takes around 1-2 hours."},{"q":"What should I do if I notice unusual electricity consumption after the checkup?","a":"If you notice any abnormalities, contact our service team immediately for further assistance and evaluation."},{"q":"Are there any preventive measures to control AC costs?","a":"Yes, our experts will provide valuable advice and recommendations on optimizing AC usage to control electricity costs."}]' WHERE slug = 'ac-power-consumption-checkup';
INSERT INTO service_prices (service_id, combo_key, price) SELECT id, '', 599 FROM services WHERE slug = 'ac-power-consumption-checkup' AND NOT EXISTS (SELECT 1 FROM service_prices WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-power-consumption-checkup') AND combo_key = '');
