INSERT INTO service_costing (service_id, material, tools, resource_count, resource_cost, service_time_label, travel_cost, internal_cost, sop_md) SELECT id, NULL, 'Gas meter, Ampere meter, Multi Functional Tester', '2', 250, '30 mins', 200, 450, 'In the first step, the technician checks indoor units at a glance. The intention is to find every drop of breakdown.
Next, clean the filter with water.
Check circuit current supply, spoil smell, sensor placement; possible parts like transistor, adapter, resistance are OK.
Measure cooling efficiency.
Check the drain line for smooth water passage.
If possible, check gas pressure of the AC and the health of the compressor.
Check the Distribution Board electricity supply.
Check main line current supply in the AC. If it''s high, find the reason, then provide a possible solution.
For a solution requiring any components or service, align with the customer about the bill.
Provide an estimate cost of the customer''s AC.
If costs are high, suggest how to reduce them — e.g. set temperature to 24 degrees, install AC per the coverage area of the room, avoid peak-hour use, service every 2 months.
Define an overall suggestion for how to improve low current consumption and cost.' FROM services WHERE slug = 'ac-power-consumption-checkup' AND NOT EXISTS (SELECT 1 FROM service_costing WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-power-consumption-checkup'));
UPDATE service_costing SET material = NULL, tools = 'Gas meter, Ampere meter, Multi Functional Tester', resource_count = '2', resource_cost = 250, service_time_label = '30 mins', travel_cost = 200, internal_cost = 450, sop_md = 'In the first step, the technician checks indoor units at a glance. The intention is to find every drop of breakdown.
Next, clean the filter with water.
Check circuit current supply, spoil smell, sensor placement; possible parts like transistor, adapter, resistance are OK.
Measure cooling efficiency.
Check the drain line for smooth water passage.
If possible, check gas pressure of the AC and the health of the compressor.
Check the Distribution Board electricity supply.
Check main line current supply in the AC. If it''s high, find the reason, then provide a possible solution.
For a solution requiring any components or service, align with the customer about the bill.
Provide an estimate cost of the customer''s AC.
If costs are high, suggest how to reduce them — e.g. set temperature to 24 degrees, install AC per the coverage area of the room, avoid peak-hour use, service every 2 months.
Define an overall suggestion for how to improve low current consumption and cost.' WHERE service_id = (SELECT id FROM services WHERE slug = 'ac-power-consumption-checkup');

-- AC Jet Wash
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-jet-wash', 'AC Jet Wash', 'High-pressure jet wash of the indoor and outdoor units.', 90, 3, 1, 'AC Jet Wash Service utilizes high-pressure jet washing techniques to deep clean and remove accumulated dirt, debris, and contaminants from your air conditioning unit. This service not only enhances the unit''s efficiency but also ensures improved air quality and optimal cooling performance, extending the lifespan of your AC system.', '["Outdoor and Indoor Unit Jet Wash: Thorough cleaning of both the outdoor and indoor units using high-pressure water to remove dust, dirt, and debris.","Air Filter Cleaning: Cleaning or replacement of air filters for optimal air quality and AC performance.","Blower Fan Cleaning: Cleaning of the blower fan for improved airflow.","Drainage System Inspection: Inspection and cleaning of the drainage system to prevent water leakage issues.","Coolant Level Check: Verification and adjustment of the coolant level for optimal cooling.","General Inspection: Overall inspection of the AC unit to identify any potential issues."]', '["The service does not cover the cost of gas refilling if needed.","The service does not include any repair work. If repairs are needed, our team will provide recommendations and a separate quotation.","Any required replacement parts are not included in the service cost and will be quoted separately.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How often should I schedule an AC Jet Wash service?","a":"It is recommended to schedule an AC Jet Wash service every 6 months for optimal performance."},{"q":"What if my AC is under warranty?","a":"Please check if taking a service from external service providers would void your manufacturer warranty. If such is the case, please go ahead with an OEM service provider only."},{"q":"Is the service safe for my AC unit?","a":"Yes, our technicians are trained to perform the service safely without causing any damage to your AC unit."},{"q":"Can this service fix cooling issues?","a":"While the service improves AC efficiency, any underlying issues affecting cooling may require additional diagnosis and repair."},{"q":"Is there a warranty for the service?","a":"Yes, the service comes with a 7 day service warranty."},{"q":"Do I need to be present during the service?","a":"It''s preferable to have someone at home during the service, but our team can coordinate with you for access if needed."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-jet-wash');
UPDATE services SET name = 'AC Jet Wash', short_desc = 'High-pressure jet wash of the indoor and outdoor units.', duration_min = 90, sort = 3, active = 1, about_md = 'AC Jet Wash Service utilizes high-pressure jet washing techniques to deep clean and remove accumulated dirt, debris, and contaminants from your air conditioning unit. This service not only enhances the unit''s efficiency but also ensures improved air quality and optimal cooling performance, extending the lifespan of your AC system.', included_json = '["Outdoor and Indoor Unit Jet Wash: Thorough cleaning of both the outdoor and indoor units using high-pressure water to remove dust, dirt, and debris.","Air Filter Cleaning: Cleaning or replacement of air filters for optimal air quality and AC performance.","Blower Fan Cleaning: Cleaning of the blower fan for improved airflow.","Drainage System Inspection: Inspection and cleaning of the drainage system to prevent water leakage issues.","Coolant Level Check: Verification and adjustment of the coolant level for optimal cooling.","General Inspection: Overall inspection of the AC unit to identify any potential issues."]', not_included_json = '["The service does not cover the cost of gas refilling if needed.","The service does not include any repair work. If repairs are needed, our team will provide recommendations and a separate quotation.","Any required replacement parts are not included in the service cost and will be quoted separately.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', faqs_json = '[{"q":"How often should I schedule an AC Jet Wash service?","a":"It is recommended to schedule an AC Jet Wash service every 6 months for optimal performance."},{"q":"What if my AC is under warranty?","a":"Please check if taking a service from external service providers would void your manufacturer warranty. If such is the case, please go ahead with an OEM service provider only."},{"q":"Is the service safe for my AC unit?","a":"Yes, our technicians are trained to perform the service safely without causing any damage to your AC unit."},{"q":"Can this service fix cooling issues?","a":"While the service improves AC efficiency, any underlying issues affecting cooling may require additional diagnosis and repair."},{"q":"Is there a warranty for the service?","a":"Yes, the service comes with a 7 day service warranty."},{"q":"Do I need to be present during the service?","a":"It''s preferable to have someone at home during the service, but our team can coordinate with you for access if needed."}]' WHERE slug = 'ac-jet-wash';
