-- AC Master Service
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-master-service', 'AC Master Service', 'Full dismantle-and-wash of indoor and outdoor units, inside and out.', 120, 4, 1, 'AC Master Wash is a detailed cleaning service for your unit, covering internal and external components to remove dust and contaminants. This premium service aims to optimize performance, enhance air quality, and extend your AC unit''s lifespan.', '["Dismantling Cover and Wash of Indoor & Outdoor Unit: Thorough dismantling and washing of both the indoor and outdoor units for complete cleanliness.","Surface Cleaning of the Indoor Unit: Wiping and cleaning the surface of the indoor unit to remove dust and debris.","AC Filter Cleaning with Air Conditioner Brush: Cleaning the AC filter using a specialized brush to ensure optimal air quality.","AC Panel Cleaning: Detailed cleaning of the AC panel to enhance the unit''s overall aesthetics.","Flushing the Drainage System: Comprehensive flushing of the drainage system to prevent clogs and water accumulation.","Compressor Health Check: Thorough examination of the compressor to ensure it''s in good health.","Gas Level Check: Checking and adjusting the gas levels for efficient cooling.","Checking and Testing of Electrical Parts: In-depth inspection and testing of all electrical components for safety and functionality.","Minor Problem-Fixing (Without Accessories & Gas): Addressing minor issues identified during the service, excluding major repairs, accessories, or gas refilling."]', '["The service does not cover the cost of gas refilling if needed.","The service does not include any repair work. If repairs are needed, our team will provide recommendations and a separate quotation.","Any required replacement parts are not included in the service cost and will be quoted separately.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How often should I schedule an AC Master Wash service?","a":"It is recommended to schedule this Master service annually for optimal AC maintenance."},{"q":"Is dismantling the units safe for my AC?","a":"Yes, our technicians are trained to dismantle and reassemble units safely without causing damage."},{"q":"What is the duration of the service?","a":"The duration may vary based on the size and condition of the AC unit but typically takes a few hours."},{"q":"What if my AC is under warranty?","a":"Please check if taking a service from external service providers would void your manufacturer warranty. If such is the case, please go ahead with an OEM service provider only."},{"q":"Is the service safe for my AC unit?","a":"Yes, our technicians are trained to perform the service safely without causing any damage to your AC unit."},{"q":"Can this service fix cooling issues?","a":"While the service improves AC efficiency, any underlying issues affecting cooling may require additional diagnosis and repair."},{"q":"Is there a warranty for the service?","a":"Yes, the service comes with a 7 day service warranty."},{"q":"Do I need to be present during the service?","a":"It''s preferable to have someone at home during the service, but our team can coordinate with you for access if needed."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-master-service');
