le)","Other services (if taken)"]', faqs_json = '[{"q":"How often should I schedule an AC Master Wash service?","a":"It is recommended to schedule this Master service annually for optimal AC maintenance."},{"q":"Is dismantling the units safe for my AC?","a":"Yes, our technicians are trained to dismantle and reassemble units safely without causing damage."},{"q":"What is the duration of the service?","a":"The duration may vary based on the size and condition of the AC unit but typically takes a few hours."},{"q":"What if my AC is under warranty?","a":"Please check if taking a service from external service providers would void your manufacturer warranty. If such is the case, please go ahead with an OEM service provider only."},{"q":"Is the service safe for my AC unit?","a":"Yes, our technicians are trained to perform the service safely without causing any damage to your AC unit."},{"q":"Can this service fix cooling issues?","a":"While the service improves AC efficiency, any underlying issues affecting cooling may require additional diagnosis and repair."},{"q":"Is there a warranty for the service?","a":"Yes, the service comes with a 7 day service warranty."},{"q":"Do I need to be present during the service?","a":"It''s preferable to have someone at home during the service, but our team can coordinate with you for access if needed."}]' WHERE slug = 'ac-master-service';
