-- AC Water Drop Solution
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-water-drop-solution', 'AC Water Drop Solution', 'Diagnose and fix water leakage from your AC unit.', 60, 6, 1, 'AC Water Drop Solution efficiently addresses and resolves water leakage issues in your air conditioning unit, ensuring optimal performance, preventing damage, and providing a reliable cooling system.', '["Inspection: Thorough examination of the AC unit to identify the source of water leakage.","Cleaning Drainage System: Clearing clogs and ensuring proper drainage flow.","Sealant Application: Applying suitable sealant to fix minor leaks and prevent future issues.","Condensation Coil Check: Verifying the condition of the condensation coil to prevent water buildup.","Testing Operation: Conducting tests to ensure the AC functions efficiently without water leakage."]', '["Extensive repairs requiring replacement of significant components.","Replenishing refrigerant gas is not included in this service.","Costs associated with replacing damaged AC parts.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"What causes water drops from my AC?","a":"Water drops can be due to clogged drain lines, damaged coils, or improper installation."},{"q":"Is this service suitable for all types of AC units?","a":"Yes, the AC Water Drop Solution is designed for various AC models and types."},{"q":"How long does the service take?","a":"The duration depends on the complexity of the issue but typically ranges from 1 to 2 hours."},{"q":"Will this service prevent future water leakage?","a":"The application of sealant aims to address current issues and prevent minor leaks in the future."},{"q":"Do I need to turn off my AC before the service?","a":"Yes, it is advisable to turn off the AC before the technician arrives for safety reasons."},{"q":"What if the problem persists after the service?","a":"We provide a service warranty, and if issues persist, please contact us within the warranty period for a re-evaluation."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-water-drop-solution');
