-- AC Gas Charge
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-gas-charge', 'AC Gas Charge', 'Refrigerant top-up with pressure and leak check.', 60, 7, 1, 'AC Gas Charge is a service dedicated to replenishing the refrigerant levels in your air conditioning unit, ensuring optimal cooling efficiency and maintaining the overall performance of your AC system.', '["Refrigerant Gas Refill: Adding the appropriate amount of refrigerant gas to the AC unit.","Pressure and Leak Check: Ensuring the system is pressurized correctly and checking for any leaks.","Performance Testing: Verifying the AC''s cooling performance after the gas refill.","Minor Repairs: Addressing minor issues related to the gas refill process.","7 Days Service Warranty: Providing a warranty period for the service."]', '["Extensive repairs requiring replacement of significant components.","Costs associated with replacing damaged AC parts.","Services not directly related to gas refill, such as cleaning or maintenance.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How often does an AC need a gas refill?","a":"The frequency depends on factors like AC usage, system age, and potential leaks. Generally, it is needed when cooling efficiency drops."},{"q":"How long does the gas refill process take?","a":"The duration varies but typically takes 1 to 2 hours, depending on the AC system."},{"q":"Is it normal for the AC to lose gas over time?","a":"Yes, gradual refrigerant loss can occur due to small leaks, and periodic refills may be necessary."},{"q":"What are signs that my AC needs a gas refill?","a":"Reduced cooling efficiency, longer cooling times, or warm air blowing from the AC are indicators."},{"q":"Can I schedule a gas refill if my AC is not cooling well?","a":"Yes, gas refills are recommended when cooling efficiency is compromised. Our technicians can assess and recommend the appropriate solution."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-gas-charge');
UPDATE services SET name = 'AC Gas Charge', short_desc = 'Refrigerant top-up with pressure and leak check.', duration_min = 60, sort = 7, active = 1, about_md = 'AC Gas Charge is a service dedicated to replenishing the refrigerant levels in your air conditioning unit, ensuring optimal cooling efficiency and maintaining the overall performance of your AC system.', included_json = '["Refrigerant Gas Refill: Adding the appropriate amount of refrigerant gas to the AC unit.","Pressure and Leak Check: Ensuring the system is pressurized correctly and checking for any leaks.","Performance Testing: Verifying the AC''s cooling performance after the gas refill.","Minor Repairs: Addressing minor issues related to the gas refill process.","7 Days Service Warranty: Providing a warranty period for the service."]', not_included_json = '["Extensive repairs requiring replacement of significant components.","Costs associated with replacing damaged AC parts.","Services not directly related to gas refill, such as cleaning or maintenance.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Transportation (if applicable)","Other services (if taken)"]', faqs_json = '[{"q":"How often does an AC need a gas refill?","a":"The frequency depends on factors like AC usage, system age, and potential leaks. Generally, it is needed when cooling efficiency drops."},{"q":"How long does the gas refill process take?","a":"The duration varies but typically takes 1 to 2 hours, depending on the AC system."},{"q":"Is it normal for the AC to lose gas over time?","a":"Yes, gradual refrigerant loss can occur due to small leaks, and periodic refills may be necessary."},{"q":"What are signs that my AC needs a gas refill?","a":"Reduced cooling efficiency, longer cooling times, or warm air blowing from the AC are indicators."},{"q":"Can I schedule a gas refill if my AC is not cooling well?","a":"Yes, gas refills are recommended when cooling efficiency is compromised. Our technicians can assess and recommend the appropriate solution."}]' WHERE slug = 'ac-gas-charge';
