-- AC Leak Repair
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-leak-repair', 'AC Leak Repair', 'Locate and seal refrigerant leaks, then refill and re-test.', NULL, 8, 1, 'AC Leak Repair is a service designed to identify and fix refrigerant leaks in your air conditioning unit, preventing loss of coolant, ensuring efficient cooling, and preserving the longevity of your AC system.', '["Leak Detection: Utilizing advanced tools to identify the location of refrigerant leaks.","Sealing Leaks: Repairing or sealing identified leaks in the AC system.","Pressure Testing: Ensuring the system is pressurized correctly after leak repair.","Refrigerant Refill: Adding the appropriate amount of refrigerant post-repair.","Performance Testing: Verifying the AC''s cooling performance after leak repair.","Minor Repairs: Addressing minor issues related to the leak repair process.","7 Days Service Warranty: Providing a warranty period for the service."]', '["Extensive repairs requiring replacement of significant components.","Costs associated with replacing damaged AC parts not related to leaks.","Services not directly related to leak repair, such as cleaning or maintenance.","Nitrogen wash price (if applicable)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How do I know if my AC has a refrigerant leak?","a":"Indicators include reduced cooling efficiency, hissing sounds, or ice buildup on the evaporator coils."},{"q":"Is AC refrigerant harmful to health?","a":"While inhalation of refrigerant is not recommended, the amount used in AC systems is generally safe. Our technicians follow safety protocols during repairs."},{"q":"How long does it take to repair an AC leak?","a":"The duration depends on the complexity of the leak. Technicians will provide an estimate after leak detection."},{"q":"Can all AC leaks be repaired?","a":"Most leaks can be repaired, but it depends on factors like the location and severity of the leak. Our technicians will assess and advise accordingly."},{"q":"Do you use environmentally friendly refrigerants for the refill?","a":"Yes, we use refrigerants that comply with environmental standards and regulations."},{"q":"Is it normal for an AC to develop leaks over time?","a":"Yes, small leaks can occur due to wear and tear, and regular maintenance can help identify and address them."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-leak-repair');
UPDATE services SET name = 'AC Leak Repair', short_desc = 'Locate and seal refrigerant leaks, then refill and re-test.', duration_min = NULL, sort = 8, active = 1, about_md = 'AC Leak Repair is a service designed to identify and fix refrigerant leaks in your air conditioning unit, preventing loss of coolant, ensuring efficient cooling, and preserving the longevity of your AC system.', included_json = '["Leak Detection: Utilizing advanced tools to identify the location of refrigerant leaks.","Sealing Leaks: Repairing or sealing identified leaks in the AC system.","Pressure Testing: Ensuring the system is pressurized correctly after leak repair.","Refrigerant Refill: Adding the appropriate amount of refrigerant post-repair.","Performance Testing: Verifying the AC''s cooling performance after leak repair.","Minor Repairs: Addressing minor issues related to the leak repair process.","7 Days Service Warranty: Providing a warranty period for the service."]', not_included_json = '["Extensive repairs requiring replacement of significant components.","Costs associated with replacing damaged AC parts not related to leaks.","Services not directly related to leak repair, such as cleaning or maintenance.","Nitrogen wash price (if applicable)","Transportation (if applicable)","Other services (if taken)"]', faqs_json = '[{"q":"How do I know if my AC has a refrigerant leak?","a":"Indicators include reduced cooling efficiency, hissing sounds, or ice buildup on the evaporator coils."},{"q":"Is AC refrigerant harmful to health?","a":"While inhalation of refrigerant is not recommended, the amount used in AC systems is generally safe. Our technicians follow safety protocols during repairs."},{"q":"How long does it take to repair an AC leak?","a":"The duration depends on the complexity of the leak. Technicians will provide an estimate after leak detection."},{"q":"Can all AC leaks be repaired?","a":"Most leaks can be repaired, but it depends on factors like the location and severity of the leak. Our technicians will assess and advise accordingly."},{"q":"Do you use environmentally friendly refrigerants for the refill?","a":"Yes, we use refrigerants that comply with environmental standards and regulations."},{"q":"Is it normal for an AC to develop leaks over time?","a":"Yes, small leaks can occur due to wear and tear, and regular maintenance can help identify and address them."}]' WHERE slug = 'ac-leak-repair';
