-- AC Circuit Repair or Replacement
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-circuit-repair-replacement', 'AC Circuit Repair or Replacement', 'Diagnose and fix faults in your AC electrical circuit.', NULL, 9, 1, 'AC Circuit Repair/Replacement is a service focused on identifying and fixing issues within the electrical circuit of your air conditioning unit, ensuring proper functioning, safety, and optimal performance.', '["Circuit Inspection: Thorough examination of the AC circuit for faults or damage.","Fault Diagnosis: Identifying and diagnosing issues affecting the AC circuit.","Minor Repairs: Addressing small faults and repairing minor issues in the circuit.","Component Replacement: Replacing damaged or faulty components within the AC circuit.","Circuit Testing: Verifying the functionality of the repaired or replaced circuit.","Performance Testing: Ensuring the AC unit operates efficiently after the circuit repair or replacement.","7 Days Service Warranty: Providing a warranty period for the service."]', '["Extensive repairs requiring a complete overhaul of the AC system.","Costs associated with replacing the entire AC unit.","Services not directly related to circuit repair or replacement.","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How can I identify if my AC circuit is faulty?","a":"Signs include frequent tripping of the circuit breaker, inconsistent cooling, or unusual sounds. Our technicians can perform a detailed inspection."},{"q":"Can a faulty AC circuit lead to other issues?","a":"Yes, a malfunctioning circuit can affect the overall performance of the AC unit and lead to more significant problems."},{"q":"What causes AC circuit faults?","a":"Common causes include electrical surges, wear and tear, or component failure. Our technicians will assess and provide details."},{"q":"How long does it take to repair or replace an AC circuit?","a":"The duration depends on the complexity of the issue. Our technicians will provide an estimate after the initial inspection."},{"q":"Can you replace specific components of the circuit, or is it an all-or-nothing repair?","a":"We prioritize cost-effective solutions. If individual components can be replaced, we''ll do so; otherwise, we''ll recommend the best course of action."},{"q":"Is it more cost-effective to repair or replace an AC circuit?","a":"Our technicians will evaluate the extent of the damage and provide a recommendation based on cost-effectiveness and long-term benefits."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-circuit-repair-replacement');
UPDATE services SET name = 'AC Circuit Repair or Replacement', short_desc = 'Diagnose and fix faults in your AC electrical circuit.', duration_min = NULL, sort = 9, active = 1, about_md = 'AC Circuit Repair/Replacement is a service focused on identifying and fixing issues within the electrical circuit of your air conditioning unit, ensuring proper functioning, safety, and optimal performance.', included_json = '["Circuit Inspection: Thorough examination of the AC circuit for faults or damage.","Fault Diagnosis: Identifying and diagnosing issues affecting the AC circuit.","Minor Repairs: Addressing small faults and repairing minor issues in the circuit.","Component Replacement: Replacing damaged or faulty components within the AC circuit.","Circuit Testing: Verifying the functionality of the repaired or replaced circuit.","Performance Testing: Ensuring the AC unit operates efficiently after the circuit repair or replacement.","7 Days Service Warranty: Providing a warranty period for the service."]', not_included_json = '["Extensive repairs requiring a complete overhaul of the AC system.","Costs associated with replacing the entire AC unit.","Services not directly related to circuit repair or replacement.","Transportation (if applicable)","Other services (if taken)"]', faqs_json = '[{"q":"How can I identify if my AC circuit is faulty?","a":"Signs include frequent tripping of the circuit breaker, inconsistent cooling, or unusual sounds. Our technicians can perform a detailed inspection."},{"q":"Can a faulty AC circuit lead to other issues?","a":"Yes, a malfunctioning circuit can affect the overall performance of the AC unit and lead to more significant problems."},{"q":"What causes AC circuit faults?","a":"Common causes include electrical surges, wear and tear, or component failure. Our technicians will assess and provide details."},{"q":"How long does it take to repair or replace an AC circuit?","a":"The duration depends on the complexity of the issue. Our technicians will provide an estimate after the initial inspection."},{"q":"Can you replace specific components of the circuit, or is it an all-or-nothing repair?","a":"We prioritize cost-effective solutions. If individual components can be replaced, we''ll do so; otherwise, we''ll recommend the best course of action."},{"q":"Is it more cost-effective to repair or replace an AC circuit?","a":"Our technicians will evaluate the extent of the damage and provide a recommendation based on cost-effectiveness and long-term benefits."}]' WHERE slug = 'ac-circuit-repair-replacement';
