-- AC Capacitor Replacement
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-capacitor-replacement', 'AC Capacitor Replacement', 'Replace a faulty or worn-out AC capacitor.', 60, 10, 1, 'AC Capacitor Replacement is a service aimed at replacing a faulty or worn-out capacitor in your air conditioning unit, ensuring proper electrical function, efficient cooling, and optimal performance of your AC system.', '["Capacitor Inspection: Comprehensive assessment of the AC capacitor for functionality.","Fault Diagnosis: Identifying issues and determining the need for capacitor replacement.","Capacitor Replacement: Professional replacement of the faulty capacitor with a new one.","Testing and Calibration: Verifying the performance and calibrating the new capacitor.","Performance Testing: Ensuring the AC unit operates efficiently after the capacitor replacement.","7 Days Service Warranty: Providing a warranty period for the service."]', '["Replacement or repair of components beyond the capacitor.","Costs associated with replacing the entire AC unit.","Services not directly related to capacitor faults.","Gas refill is not included in the service."]', '[{"q":"How can I tell if my AC capacitor is faulty?","a":"Signs include the AC unit not starting, irregular cooling, or strange noises. Our technicians can perform a detailed inspection."},{"q":"What causes an AC capacitor to fail?","a":"Common causes include electrical surges, wear and tear, or manufacturing defects. Our technicians will assess and provide details."},{"q":"Is a faulty capacitor a common AC issue?","a":"Yes, capacitors can wear out over time, especially in regions with frequent temperature fluctuations."},{"q":"Can a faulty capacitor damage other AC components?","a":"Yes, a malfunctioning capacitor can strain other components, potentially leading to more significant issues if not addressed promptly."},{"q":"How long does it take to replace an AC capacitor?","a":"The duration depends on the complexity of the replacement. Our technicians will provide an estimate after the initial inspection."},{"q":"Is capacitor replacement cost-effective compared to repairing other components?","a":"Our technicians will evaluate the extent of the damage and recommend the most cost-effective solution for your specific situation."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-capacitor-replacement');
UPDATE services SET name = 'AC Capacitor Replacement', short_desc = 'Replace a faulty or worn-out AC capacitor.', duration_min = 60, sort = 10, active = 1, about_md = 'AC Capacitor Replacement is a service aimed at replacing a faulty or worn-out capacitor in your air conditioning unit, ensuring proper electrical function, efficient cooling, and optimal performance of your AC system.', included_json = '["Capacitor Inspection: Comprehensive assessment of the AC capacitor for functionality.","Fault Diagnosis: Identifying issues and determining the need for capacitor replacement.","Capacitor Replacement: Professional replacement of the faulty capacitor with a new one.","Testing and Calibration: Verifying the performance and calibrating the new capacitor.","Performance Testing: Ensuring the AC unit operates efficiently after the capacitor replacement.","7 Days Service Warranty: Providing a warranty period for the service."]', not_included_json = '["Replacement or repair of components beyond the capacitor.","Costs associated with replacing the entire AC unit.","Services not directly related to capacitor faults.","Gas refill is not included in the service."]', faqs_json = '[{"q":"How can I tell if my AC capacitor is faulty?","a":"Signs include the AC unit not starting, irregular cooling, or strange noises. Our technicians can perform a detailed inspection."},{"q":"What causes an AC capacitor to fail?","a":"Common causes include electrical surges, wear and tear, or manufacturing defects. Our technicians will assess and provide details."},{"q":"Is a faulty capacitor a common AC issue?","a":"Yes, capacitors can wear out over time, especially in regions with frequent temperature fluctuations."},{"q":"Can a faulty capacitor damage other AC components?","a":"Yes, a malfunctioning capacitor can strain other components, potentially leading to more significant issues if not addressed promptly."},{"q":"How long does it take to replace an AC capacitor?","a":"The duration depends on t