INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-installation-uninstallation', 'AC Installation & Uninstallation', 'Full install and uninstall service, indoor and outdoor units.', 240, 12, 1, 'AC Installation & Uninstallation Service provides expert assistance in both installing and uninstalling air conditioning units, ensuring a seamless and efficient process for setting up or removing your AC system with precision and care.', '["Site Inspection: Assessing the installation or uninstallation site for suitability.","Installation/Uninstallation of Indoor Unit: Proper mounting or removal of the indoor AC unit.","Installation/Uninstallation of Outdoor Unit: Secure placement or removal of the outdoor AC unit.","Electrical Wiring: Connecting or disconnecting electrical wiring for the AC unit.","Piping Connection: Establishing or disconnecting refrigerant piping.","Drain Pipe Setup: Installing or removing the drain pipe for proper condensation drainage.","Testing & Calibration: Verifying the AC unit''s functionality and calibrating settings.","7 Days Service Warranty: Providing a warranty period for the service."]', '["Any electrical work beyond the AC unit''s direct installation.","Costs associated with additional materials needed for installation.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How long does it take to install/uninstall an AC unit?","a":"The duration varies based on the complexity of the installation or uninstallation. Our technicians will provide an estimate after the initial inspection."},{"q":"Can the AC unit be installed in any room?","a":"Our technicians will assess the room''s suitability during the site inspection. Certain factors like room size and ventilation are considered."},{"q":"Is uninstallation included if I''m moving to a new location?","a":"Uninstallation is included, and we can reinstall the unit at the new location if requested. Additional charges may apply for transportation."},{"q":"Do I need to provide any materials for the installation?","a":"Our service includes standard installation materials. If specific materials are required, our technicians will inform you in advance."},{"q":"Can you install multiple AC units in different rooms during the same service?","a":"Each installation or uninstallation service is typically specific to one AC unit. For multiple units, additional service requests may be needed."},{"q":"Is there any structural modification required for installation?","a":"Our service is designed for standard installations without major structural changes. If modifications are needed, our technicians will advise accordingly."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-installation-uninstallation');
