INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-uninstallation', 'AC Uninstallation', 'Careful removal of your AC unit for relocation or replacement.', 90, 14, 1, 'AC Uninstallation Service offers professional and efficient removal of your air conditioning unit, ensuring careful dismantling and disconnection to facilitate relocation or replacement while maintaining the integrity of the unit.', '["Removal of Indoor Unit: Safe and systematic removal of the indoor AC unit.","Disconnection of Electrical Wiring: Safely disconnecting the AC unit from the electrical supply.","Uninstallation of Outdoor Unit: Proper dismantling and removal of the outdoor AC unit.","Recovery of Refrigerant: Proper retrieval and disposal of refrigerant as per safety guidelines.","Piping Disconnection: Careful disconnection of refrigerant piping.","Drain Pipe Removal: Disassembling and removing the drain pipe.","Professional Advice: Guidance on maintaining AC components during storage or relocation.","7 Days Service Warranty: Warranty period for the uninstallation service."]', '["Beyond the direct uninstallation of the AC unit.","Changes to walls, ceilings, or structures during uninstallation.","Costs for extra materials needed for uninstallation.","Hanging Charge 499 tk (If applicable for the outdoor unit)","Components/Materials or Parts (if used)","Transportation (if applicable)","Other services (if taken)"]', '[{"q":"How long does it take to uninstall an AC unit?","a":"The duration varies depending on the complexity of the uninstallation. Our technicians will provide an estimate during the site inspection."},{"q":"Can the AC unit be reinstalled after uninstallation?","a":"Yes, our technicians can reinstall the AC unit at a different location if needed. Additional installation charges may apply."},{"q":"Is recovery of refrigerant included in the service?","a":"Yes, our service includes the safe recovery and disposal of refrigerant."},{"q":"Can I schedule uninstallation for multiple AC units during the same service?","a":"Each uninstallation service is typically specific to one AC unit. For multiple units, additional service requests may be needed."},{"q":"What should I do with the AC unit after uninstallation?","a":"Our technicians can provide advice on storage or relocation. If needed, we offer installation services at a new location."},{"q":"Is the 7-day service warranty applicable to all aspects of uninstallation?","a":"Yes, the warranty covers the entire uninstallation process. If issues arise within the warranty period, we''ll address them promptly."},{"q":"Can I keep the AC components for future use?","a":"Yes, you can keep the components for future use. Our technicians will provide guidance on proper storage."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-uninstallation');
