-- Corporate AC Service
INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-corporate-service', 'Corporate AC Service', 'Bulk and commercial AC servicing with a dedicated account manager.', NULL, 15, 1, 'At Solvex you can hire an expert AC repair service near you. Our professional Service Providers will give you the best AC repair service. From general inspection, to changing AC parts you can avail every AC related service within a few moments.

Our Service List

1. AC Checkup Service: AC Checkup service offers only the diagnosis of your Air Conditioner by an expert technician who performs initial tests for problem identification.

2. AC Basic Servicing: AC Basic service offers primary diagnosis, filter cleaning, test and identify problems by an expert AC technician.

3. AC Jet Wash: AC Jet Wash offers detailed cleaning of the indoor and outdoor units with Jet Wash Machine including minor problem-fixing (excluding materials and parts). The service charge varies on your AC amount, height, weight, and difficulties.

4. AC Master Service: AC Master Service offers detailed cleaning of the indoor and outdoor units including minor problem-fixing (excluding materials and parts). The service charge varies on your AC amount, height, weight and difficulties.

5. AC Gas Charge: This service offers a performance checkup and post gas refill. If there is a leakage; most of the time AC can be fixed onsite but sometimes it might take a longer time. For that, you have to wait for 1 or 2 days.

6. AC Water Drop Solution: This service offers identification of the source of dripping water from your AC and fixation water drainage system accordingly. Any additional materials/parts will be charged separately.

7. AC Shifting Service: This service is to shift your AC unit from one place or floor to the loading truck. Only the service charge is applicable for this service. The service charge varies on your AC amount, height, weight, and difficulties.

8. AC Compressor Fitting With Gas Charge: This service offers old Compressor removal and new Compressor installation. Compressor price and warranty differ as per manufacturer.

9. AC Dismantling: This service offers dismantling AC from home or workplace and disconnecting all the electrical wiring from the AC unit.

10. AC Capacitor Replacement: This service offers to replace the AC capacitor with a new one. Capacitor price and warranty differ as per manufacturer.

11. AC Circuit Repairing: This service offers to repair the circuits of your AC. Circuit box price and warranty differ as per manufacturer.

Why Choose Us

- Dedicated Key Account Manager (KAM): We believe in personalized service. Each client is assigned a Dedicated Key Account Manager to ensure seamless communication, address specific needs, and provide tailored solutions.

- Expert and Reliable Technicians: Our team consists of highly skilled and experienced technicians. You can trust us to deliver reliable services, backed by expertise in the field.

- Professional Consultation: We offer professional consultation to guide you through service options, answer queries, and provide recommendations for optimal solutions tailored to your requirements.

- Best Price Assurance: Quality service doesn''t have to break the bank. We are committed to providing competitive and transparent pricing, ensuring you get the best value for your investment.', NULL, NULL, '[{"q":"How often should I schedule commercial AC service?","a":"Regular service is recommended at least twice a year for optimal performance."},{"q":"Can you service multiple AC units within the same appointment?","a":"Yes, our technicians can service multiple units during a single appointment. Please provide details during scheduling."},{"q":"What is the typical duration of a commercial AC service?","a":"The service duration varies based on the number of units and their complexity. Our technicians will provide an estimate during the initial inspection."},{"q":"Is the 7-day service warranty applicable to all aspects of the service?","a":"Yes, the warranty covers the entire scope of the service. If issues arise within the warranty period, we''ll address them promptly."},{"q":"Do you offer emergency commercial AC service?","a":"Yes, we provide emergency services. Please contact our customer support for immediate assistance."},{"q":"Can you handle major repairs during the service?","a":"Major repairs may require a separate appointment due to time constraints during routine service. Our technicians will assess and provide recommendations."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-corporate-service');
