INSERT INTO services (category_id, slug, name, short_desc, duration_min, sort, active, about_md, included_json, not_included_json, faqs_json, created_at) SELECT id, 'ac-vrf-inspection', 'VRF AC Inspection', 'Comprehensive diagnostic for Variable Refrigerant Flow systems.', NULL, 16, 1, 'VRF AC Inspection involves a comprehensive assessment of Variable Refrigerant Flow (VRF) air conditioning systems, including checking refrigerant levels, inspecting components for wear and tear, and ensuring proper functionality. This service helps identify any issues and ensures efficient operation of your VRF AC system.', '["Unit Inspection: Thorough examination of the VRF AC indoor & outdoor unit to assess its overall condition.","Filter Check and Cleaning: Inspection of filters to ensure optimal air quality and system efficiency.","Coil Inspection: Examination of coils for any dust, debris, or issues affecting heat exchange.","Refrigerant Level Check: Assessment of refrigerant levels to ensure they are within the recommended range.","Electrical Component Check: Inspection of electrical components for signs of wear, damage, or potential issues.","Condensate Drain Inspection: Examination of the condensate drain to prevent clogs and water damage.","Thermostat Testing: Testing and calibration of the thermostat for accurate temperature control.","System Performance Check: Overall assessment of the VRF system''s performance and efficiency.","Recommendations: Providing recommendations & quotations for any necessary repairs or improvements."]', '["Full system repairs or major component replacements beyond the inspection scope.","System Efficiency Guarantee: The service does not come with a guarantee of improved system efficiency; it is primarily diagnostic."]', '[{"q":"How often should I schedule a VRF Air Condition Inspection?","a":"We recommend scheduling an inspection annually to ensure the system''s optimal performance."},{"q":"Is VRF air conditioning suitable for residential use?","a":"VRF systems are commonly used in commercial settings, but they can be adapted for larger residential spaces."},{"q":"What are the signs that my VRF system needs inspection?","a":"Reduced cooling or heating efficiency, unusual sounds, or inconsistent airflow are indicators that an inspection may be needed."},{"q":"Can I schedule the inspection for a specific date and time?","a":"Yes, we offer flexible scheduling options to accommodate your preferred date and time for the service."},{"q":"How long does a VRF Air Condition Inspection typically take?","a":"The duration depends on the system size and complexity but usually takes 1-2 hours."},{"q":"Are your technicians trained to work with VRF systems?","a":"Yes, our technicians are experienced and trained to inspect and assess VRF air conditioning systems."},{"q":"What happens if the inspection reveals issues with my VRF system?","a":"Our technicians will provide detailed recommendations, and you can decide whether to proceed with any necessary repairs."}]', unixepoch()*1000 FROM categories WHERE slug = 'air-conditioner' AND NOT EXISTS (SELECT 1 FROM services WHERE slug = 'ac-vrf-inspection');
